package com.coffeeshop.repository;
import com.coffeeshop.dto.CustomerCommands;import com.coffeeshop.exception.DatabaseException;import com.coffeeshop.model.CustomerModels;import javax.sql.DataSource;import java.sql.*;import java.util.*;
public final class JdbcCustomerRepository implements CustomerRepository{private final DataSource ds;public JdbcCustomerRepository(DataSource d){ds=Objects.requireNonNull(d);}public List<CustomerModels.Customer>find(String search,Boolean active){String sql="SELECT customer_id,customer_number,first_name,last_name,legal_name,tax_registration_number,phone,email,notes,is_active,row_version FROM dbo.customers WHERE (? IS NULL OR is_active=?) AND (?='' OR customer_number LIKE ? OR first_name LIKE ? OR COALESCE(last_name,'') LIKE ? OR COALESCE(phone,'') LIKE ? OR COALESCE(email,'') LIKE ?) ORDER BY first_name,last_name";try(Connection c=ds.getConnection();PreparedStatement s=c.prepareStatement(sql)){if(active==null){s.setNull(1,Types.BIT);s.setNull(2,Types.BIT);}else{s.setBoolean(1,active);s.setBoolean(2,active);}String q=search==null?"":search.trim();s.setString(3,q);String like="%"+q+"%";for(int i=4;i<=8;i++)s.setString(i,like);try(ResultSet r=s.executeQuery()){List<CustomerModels.Customer>x=new ArrayList<>();while(r.next())x.add(map(r));return List.copyOf(x);}}catch(SQLException e){throw fail("Unable to load customers.",e);}}public List<CustomerModels.Option>activeOptions(){String sql="SELECT customer_id,customer_number,first_name,last_name FROM dbo.customers WHERE is_active=1 ORDER BY first_name,last_name";try(Connection c=ds.getConnection();PreparedStatement s=c.prepareStatement(sql);ResultSet r=s.executeQuery()){List<CustomerModels.Option>x=new ArrayList<>();while(r.next())x.add(new CustomerModels.Option(r.getLong(1),r.getString(2),(r.getString(3)+" "+Objects.toString(r.getString(4),"")).trim()));return List.copyOf(x);}catch(SQLException e){throw fail("Unable to load customers.",e);}}public long save(CustomerCommands.Save q){try(Connection c=ds.getConnection()){c.setAutoCommit(false);try{String number=q.id()==null?number(c):null;String sql=q.id()==null?"INSERT dbo.customers(customer_number,first_name,last_name,legal_name,tax_registration_number,phone,email,notes,is_active) VALUES(?,?,?,?,?,?,?,?,?)":"UPDATE dbo.customers SET first_name=?,last_name=?,legal_name=?,tax_registration_number=?,phone=?,email=?,notes=?,is_active=?,updated_at=SYSUTCDATETIME() WHERE customer_id=? AND row_version=?";long id;try(PreparedStatement s=c.prepareStatement(sql,Statement.RETURN_GENERATED_KEYS)){int i=1;if(q.id()==null)s.setString(i++,number);s.setString(i++,q.firstName());nullable(s,i++,q.lastName());nullable(s,i++,q.legalName());nullable(s,i++,q.taxNumber());nullable(s,i++,q.phone());nullable(s,i++,q.email());nullable(s,i++,q.notes());s.setBoolean(i++,q.active());if(q.id()!=null){s.setLong(i++,q.id());s.setBytes(i,q.rowVersion());one(s.executeUpdate());id=q.id();}else{s.executeUpdate();id=key(s);}}c.commit();return id;}catch(Exception e){c.rollback();throw e;}}catch(RuntimeException e){throw e;}catch(Exception e){throw fail("Unable to save the customer.",e);}}public void setActive(long id,boolean active,byte[]version){try(Connection c=ds.getConnection();PreparedStatement s=c.prepareStatement("UPDATE dbo.customers SET is_active=?,updated_at=SYSUTCDATETIME() WHERE customer_id=? AND row_version=?")){s.setBoolean(1,active);s.setLong(2,id);s.setBytes(3,version);one(s.executeUpdate());}catch(SQLException e){throw fail("Unable to update the customer.",e);}}private static CustomerModels.Customer map(ResultSet r)throws SQLException{return new CustomerModels.Customer(r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getString(8),r.getString(9),r.getBoolean(10),r.getBytes(11));}private static String number(Connection c)throws SQLException{String prefix="CUS";try(PreparedStatement s=c.prepareStatement("SELECT setting_value FROM dbo.settings WHERE setting_key='numbering.customer.prefix'");ResultSet r=s.executeQuery()){if(r.next())prefix=r.getString(1);}try(PreparedStatement s=c.prepareStatement("SELECT NEXT VALUE FOR dbo.seq_customer_number");ResultSet r=s.executeQuery()){r.next();return prefix+String.format("%08d",r.getLong(1));}}private static void nullable(PreparedStatement s,int i,String v)throws SQLException{if(v==null)s.setNull(i,Types.NVARCHAR);else s.setString(i,v);}private static void one(int n){if(n!=1)throw new IllegalStateException("This customer changed. Refresh and try again.");}private static long key(PreparedStatement s)throws SQLException{try(ResultSet r=s.getGeneratedKeys()){if(!r.next())throw new SQLException("Generated identifier unavailable");return r.getLong(1);}}private static DatabaseException fail(String m,Exception e){return new DatabaseException(m,e);}}
